    if(d<minD){minD2=minD;minD=d;}else if(d<minD2)minD2=d;
  }
  const cell=(minD2-minD)*2.5;
  const r1=Math.tanh((act-inh*0.7+bg*0.25+spiral+cell*0.4)*2.0);
  const r2=Math.tanh((act*0.6+inh*0.3-bg*0.2+spiral*0.5-cell*0.3)*1.8);
